"<body>\n"
"  <header>\n"
"    <h1>SKE-02 Gateway</h1>\n"
"    <span id=\"link\" class=\"tag\">…</span><span id=\"fw\" class=\"tag\"></span>\n"
"    <a href=\"/settings\"><button>&#9881; Настройки</button></a>\n"
"    <button class=\"warn\" onclick=\"rebootDev()\">Перезагрузить прибор</button>\n"
"    <a href=\"/wifi\"><button>Wi-Fi</button></a>\n"
"  </header>\n"
"  <div id=\"values\"></div>\n"
"  <div id=\"debug\">\n"
"    отладочная панель\n"
"    <button onclick=\"rescan()\">Пересканировать</button>\n"
"    <span class=\"tag\" id=\"ip\"></span><span class=\"tag\" id=\"rss\"></span>\n"
"    <span class=\"tag\" id=\"upt\"></span><span class=\"tag\" id=\"heap\"></span>\n"
"  </div>\n"
"  <script>\n"
"    const $ = i => document.getElementById(i);\n"
"    function hms(t) { const s = t % 60, m = (t / 60 | 0) % 60, h = t / 3600 | 0; return h ? h + 'ч ' + m + 'м' : m ? m + 'м ' + s + 'с' : s + 'с' }\n"
"    /* live values window: MeterData_t fields, names as the struct members;\n"
"     * bitwise members render as FSETPOINT_/FSTATUS_/FISR_ flag chips */\n"
"    const FLAGS = {\n"
"      setpoint: ['RATEQMAX', 'RATEHIGH', 'RATELOW', 'FLOW', 'TOTAL', 'GTOTAL', 'BATCH', 'PREEMPTION'],\n"
"      status: ['ACCESERROR', 'BATCHER_TIMEOUT', 'BATCHER_PAUSE', 'BATCHER_FINISH', 'RTCERROR', 'RAMERROR', 'REVERSE', 'LOGFULL'],\n"
"      isr: ['DOUT0', 'DOUT1', 'DOUT2', 'BUZZER', 'HIGHFREQ', 'LOWFREQ', 'DUTY', 'PHASE']\n"
"    };\n"
"    const VFLOATS = ['frequency', 'rate_raw', 'rate_fast', 'rateMLPM', 'rate', 'total_plus', 'total_minus', 'total', 'total_sum', 'totalml_plus', 'totalml_minus', 'gtotal', 'gtotalml', 'kf_value', 'batch'];\n"
"    const VUINTS = ['pulses_packet', 'pulses'];\n"
"    let vBuilt = false;\n"
"    /* rate history: ring of the last 600 s (the values poll is 1 Hz) */\n"
"    const RATE_N = 600;\n"
"    let rateHist = [], rateMin = 0, rateMax = 1;\n"
"    function ratePush(v) {\n"
"      rateHist.push(v);\n"
"      if (rateHist.length > RATE_N) rateHist.shift();\n"
"    }\n"
"    function rateDraw() {\n"
"      const cv = $('rateChart'); if (!cv) return;\n"
"      const dpr = window.devicePixelRatio || 1;\n"
"      const w = cv.offsetWidth, h = 120;\n"
"      if (cv.width !== w * dpr || cv.height !== h * dpr) { cv.width = w * dpr; cv.height = h * dpr }\n"
"      const g = cv.getContext('2d');\n"
"      g.setTransform(dpr, 0, 0, dpr, 0, 0);\n"
"      g.clearRect(0, 0, w, h);\n"
"      const n = rateHist.length;\n"
"      g.strokeStyle = '#2a3140'; g.lineWidth = 1;\n"
"      for (let k = 1; k < 4; k++) { const y = h * k / 4; g.beginPath(); g.moveTo(0, y); g.lineTo(w, y); g.stroke() }\n"
"      if (n < 2) { g.fillStyle = '#8b94a7'; g.font = '12px system-ui'; g.fillText('накопление данных…', 8, h / 2); return }\n"
"      let lo = Infinity, hi = -Infinity;\n"
"      for (const v of rateHist) { if (v < lo) lo = v; if (v > hi) hi = v }\n"
"      rateMin = lo; rateMax = hi;\n"
"      if (hi - lo < 1e-9) { lo -= 0.5; hi += 0.5 }\n"
"      const pad = (hi - lo) * 0.08; lo -= pad; hi += pad;\n"
"      const X = i => w * i / (RATE_N - 1), Y = v => h - 2 - (v - lo) / (hi - lo) * (h - 4);\n"
"      g.beginPath();\n"
"      const off = RATE_N - n; /* anchor right so the chart scrolls */\n"
"      for (let i = 0; i < n; i++) { const x = X(off + i), y = Y(rateHist[i]); i ? g.lineTo(x, y) : g.moveTo(x, y) }\n"
"      g.strokeStyle = '#7aa2f7'; g.lineWidth = 1.5; g.stroke();\n"
"      g.lineTo(X(RATE_N - 1), h); g.lineTo(X(off), h); g.closePath();\n"
"      g.fillStyle = 'rgba(122,162,247,0.15)'; g.fill();\n"
"      const last = rateHist[n - 1];\n"
"      g.fillStyle = '#d8dee9'; g.font = '12px ui-monospace,Consolas,monospace';\n"
"      g.fillText(last.toFixed(3), 8, 12);\n"
"      g.fillStyle = '#8b94a7';\n"
"      g.fillText('max ' + (rateMax).toFixed(3), w - 86, 12);\n"
"      g.fillText('min ' + (rateMin).toFixed(3), w - 86, h - 4);\n"
"    }\n"
"    window.addEventListener('resize', rateDraw);\n"
"    function vBuild() {\n"
"      let h = '<div class=\"vcard chart\"><div class=\"vname\">rate, последние 10 мин</div><canvas id=\"rateChart\"></canvas></div>';\n"
"      for (const n of VFLOATS) h += '<div class=\"vcard\"><div class=\"vname\">' + n + '</div><div class=\"vval\" id=\"vf_' + n + '\">—</div></div>';\n"
"      for (const n of VUINTS) h += '<div class=\"vcard\"><div class=\"vname\">' + n + '</div><div class=\"vval\" id=\"vf_' + n + '\">—</div></div>';\n"
"      for (const n in FLAGS) {\n"
"        h += '<div class=\"vcard wide\"><div class=\"vname\">' + n + '</div><div id=\"vb_' + n + '\">';\n"
"        FLAGS[n].forEach((b, k) => h += '<span class=\"bit\" id=\"vb_' + n + '_' + k + '\">' + b + '</span>');\n"
"        h += '</div></div>';\n"
"      }\n"
"      $('values').innerHTML = h; vBuilt = true; rateDraw();\n"
"    }\n"
"    function vApply(d) {\n"
"      for (const n of VFLOATS) { const e = $('vf_' + n); if (e && d[n] !== undefined) e.textContent = d[n] }\n"
"      for (const n of VUINTS) { const e = $('vf_' + n); if (e && d[n] !== undefined) e.textContent = d[n] }\n"
"      for (const n in FLAGS) { const v = d[n] || 0; FLAGS[n].forEach((b, k) => { const e = $('vb_' + n + '_' + k); if (e) e.className = 'bit' + ((v >> k) & 1 ? ' on' : '') }) }\n"
"    }\n"
"    async function valuesTick() {\n"
"      try {\n"
"        const d = await (await fetch('/api/values')).json();\n"
"        if (d.link !== undefined) {\n"
"          $('link').textContent = d.link ? 'UART: связь есть' : 'UART: нет связи';\n"
"          $('link').className = 'tag ' + (d.link ? 'ok' : 'bad');\n"
"        }\n"
"        if (!d.ok) { return }\n"
"        if (!vBuilt) vBuild();\n"
"        vApply(d);\n"
"        if (d.rate !== undefined) { ratePush(d.rate); rateDraw() }\n"
"      } catch (e) { }\n"
"    }\n"
"    setInterval(valuesTick, 200); valuesTick();\n"
"    async function infoTick() {\n"
"      try {\n"
"        const r = await (await fetch('/api/info')).json();\n"
"        $('fw').textContent = r.fw + ' · параметров: ' + r.count;\n"
"        $('ip').textContent = r.ip;\n"
"        $('rss').textContent = r.ap ? r.rssi + ' dBm' : r.ssid + ': ' + r.rssi + ' dBm';\n"
"        $('upt').textContent = 'uptime ' + hms(r.uptime); $('heap').textContent = 'heap ' + (r.heap / 1024 | 0) + ' KiB';\n"
"      } catch (e) { }\n"
"    }\n"
"    async function rescan() { await fetch('/api/rescan', { method: 'POST' }); infoTick() }\n"
"    function rebootDev() { if (confirm('Перезагрузить прибор?')) fetch('/api/reboot', { method: 'POST' }) }\n"
"    infoTick(); setInterval(infoTick, 5000);\n"
"  </script>\n"
"</body>\n"
"\n"
"</html>\n";

